import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;
import java.util.function.Supplier;

final class Fees {
    // functions in
    static <T> T retry(int times, Supplier<T> block) {
        RuntimeException last = null;
        for (int i = 0; i < times; i++) {
            try { return block.get(); } catch (RuntimeException e) { last = e; }
        }
        throw new IllegalStateException("gave up after " + times + " attempts", last);
    }

    // functions out: partial application
    static Function<Long, Long> feeFor(long bps) {
        return amountCents -> amountCents * bps / 10_000;
    }

    // composition is built into Function
    static Function<Long, Long> price(long bps) {
        return feeFor(bps).andThen(fee -> fee + 25).andThen(fee -> Math.min(fee, 1_000));
    }

    static <A, R> Function<A, R> memoize(Function<A, R> f) {
        Map<A, R> cache = new ConcurrentHashMap<>();
        return a -> cache.computeIfAbsent(a, f);
    }
}

