fun toAdjust(row: AdjustmentRow): (Long) -> Long = when (row.kind) {
    "flat" -> { fee -> fee + row.value }
    "discount" -> { fee -> fee * (100 - row.value) / 100 }
    "floor" -> { fee -> maxOf(fee, row.value) }
