static Function<Long, Long> toAdjust(AdjustmentRow row) {
    return switch (row.kind()) {
        case "flat" -> fee -> fee + row.value();
        case "discount" -> fee -> fee * (100 - row.value()) / 100;
        case "floor" -> fee -> Math.max(fee, row.value());
        case "cap" -> fee -> Math.min(fee, row.value());
        default -> throw new IllegalArgumentException("unknown adjustment " + row.kind());
    };
}

static Function<Long, Long> merchantFee(String country, List<AdjustmentRow> rows) {
    return rows.stream()
            .map(Fees::toAdjust)                               // 1. rows to functions
            .reduce(feeFor(country), Function::andThen);       // 2. one function, base fee first
}

Function<Long, Long> acmeFee = merchantFee("NL", acmeRows);

acmeFee.apply(100_000L);   // 1,400 -> 1,260 -> 1,260 -> 1,000
acmeFee.apply(2_000L);     // 28 -> 25 -> 50 -> 50

